import type { ReactNode } from 'react'
import { toDomId } from '../core'
import { cx } from '../lib/cx'

export interface TabPanelProps {
  /** Must match the `id` passed to the tab bar. */
  tabsId: string
  value: string
  children: ReactNode
  className?: string
}

/** Optional WAI-ARIA panel matching the ids generated by every tab bar. */
export function TabPanel({ tabsId, value, children, className }: TabPanelProps) {
  const id = `${toDomId(tabsId)}-panel-${toDomId(value)}`
  return (
    <div
      role="tabpanel"
      id={id}
      aria-labelledby={`${toDomId(tabsId)}-tab-${toDomId(value)}`}
      tabIndex={0}
      className={cx('outline-none focus-visible:ring-2', className)}
    >
      {children}
    </div>
  )
}
